  '同一域名不得绑定多个城市，多个域名可以绑定同一城市，但是前台选择城市域名跳转会以最后添加域名为基准，外部访问则不作限制！' => '同一域名不得绑定多个城市，多个域名可以绑定同一城市，但是前台选择城市域名跳转会以最后添加域名为基准，外部访问则不作限制！',
  '描述：例如设置的职位类别是“普工”，求职者创建简历时选择“普工”后可不强制填写及以上任何条件，且申请时不判断简历完整度。' => '描述：例如设置的职位类别是“普工”，求职者创建简历时选择“普工”后可不强制填写及以上任何条件，且申请时不判断简历完整度。',
