  '说明：例如设置的职位类别是“普工”，求职者创建简历时选择“普工”后可不强制填写以上任何条件，且申请时不判断简历完整度。' => '说明：例如设置的职位类别是“普工”，求职者创建简历时选择“普工”后可不强制填写以上任何条件，且申请时不判断简历完整度。',
  '可设置的等级包括：普通会员，高级会员，钻石会员等等，按照实际情况进入设置等级的区分，会员等级需满足的条件和享受的优惠' => '可设置的等级包括：普通会员，高级会员，钻石会员等等，按照实际情况进入设置等级的区分，会员等级需满足的条件和享受的优惠',
  '查看投递：针对求职者主动投递的简历，企业每天可以免费下载、查看其联系方式的数量。超出后，需花费基础套餐下载简历点数。' => '查看投递：针对求职者主动投递的简历，企业每天可以免费下载、查看其联系方式的数量。超出后，需花费基础套餐下载简历点数。',
  'you账号Review approved！例：http://www.ov6.com 全站Use 仅在HomeUse' => 'you账号Review approved！例：http://www.ov6.com 全站Use 仅在HomeUse',
  '刷新职位：每天可免费刷新职位数量，企业客户刷新职位操作，优先扣除每日免费刷新套餐。超出后，需花费基础套餐刷新点数。' => '刷新职位：每天可免费刷新职位数量，企业客户刷新职位操作，优先扣除每日免费刷新套餐。超出后，需花费基础套餐刷新点数。',
  '可设置的等级包括：普通会员，高级会员，钻石会员等等，按照实际情况去设置等级的区分，会员等级需满足的条件和享受的优惠' => '可设置的等级包括：普通会员，高级会员，钻石会员等等，按照实际情况去设置等级的区分，会员等级需满足的条件和享受的优惠',
  '实现“伪静态设置、前台列表最大展示数量、外部链接”等进行设置！伪静态可以增强网站收录友好度！运营者大部分都是开启的' => '实现“伪静态设置、前台列表最大展示数量、外部链接”等进行设置！伪静态可以增强网站收录友好度！运营者大部分都是开启的',
  '可以为企业提供个性化模板,管理员自己设计企业模板后上传到企业模板目录即可！可以设置模板价格，提供企业用户自由选择' => '可以为企业提供个性化模板,管理员自己设计企业模板后上传到企业模板目录即可！可以设置模板价格，提供企业用户自由选择',
  '可以为企业提供个性化模板，管理员自己设计企业模板后上传到企业模板目录即可！可以设置模板价格，提供企业用户自由选择' => '可以为企业提供个性化模板，管理员自己设计企业模板后上传到企业模板目录即可！可以设置模板价格，提供企业用户自由选择',
  '开启多城市并且绑定域名不支持2级目录，本地测试如 http://localhost/phpyun 请解析测试域名' => '开启多城市并且绑定域名不支持2级目录，本地测试如 http://localhost/phpyun 请解析测试域名',
  '无需下载，不占手机空间，超省流量，没有机型的限制，有触屏手机就能上网找工作机会不再稍纵即逝，它已在你轻盈的指尖上' => '无需下载，不占手机空间，超省流量，没有机型的限制，有触屏手机就能上网找工作机会不再稍纵即逝，它已在你轻盈的指尖上',
  '控制职位详情是否展示投递数量；默认：0；在设置大于0的情况下，职位投递数超过设置数量，职位详情才会显示投递数量' => '控制职位详情是否展示投递数量；默认：0；在设置大于0的情况下，职位投递数超过设置数量，职位详情才会显示投递数量',
  '$v.service_price * $discount.service_discount * 0.01 元' => '$v.service_price * $discount.service_discount * 0.01 元',
  '根据会员刷新套餐数量，设置刷新次数，每N分钟刷新一次，自动刷新需会员选择不同天数，支付一定金额，每天刷新一次' => '根据会员刷新套餐数量，设置刷新次数，每N分钟刷新一次，自动刷新需会员选择不同天数，支付一定金额，每天刷新一次',
