  '职责描述：1.负责数据中心机房整体规划、部署，架构优化、容灾优化、性能优化；2.负责数据中心基础设施...' => '职责描述：1.负责数据中心机房整体规划、部署，架构优化、容灾优化、性能优化；2.负责数据中心基础设施...',
  '该简历为未审核状态，暂时无法对其查看、邀请面试等操作，我们将尽快完成该简历的审核，对您的工作造成不便请谅解' => '该简历为未审核状态，暂时无法对其查看、邀请面试等操作，我们将尽快完成该简历的审核，对您的工作造成不便请谅解',
  '财付通是腾讯公司创办的中国领先的在线支付平台 致力于为互联网用户和企业提供安全、便捷、专业的在线支付服务。' => '财付通是腾讯公司创办的中国领先的在线支付平台 致力于为互联网用户和企业提供安全、便捷、专业的在线支付服务。',
