  '请描述你在职期间的职责范围、工作内容和工作业绩，为保护个人隐私，请不要填写手机号、QQ、微信等联系方式' => '请描述你在职期间的职责范围、工作内容和工作业绩，为保护个人隐私，请不要填写手机号、QQ、微信等联系方式',
  '采用HTML5+CSS3代码编写，更快的速度、更低的流量、更好的用户体验，真正让您随时随地轻松找工作。' => '采用HTML5+CSS3代码编写，更快的速度、更低的流量、更好的用户体验，真正让您随时随地轻松找工作。',
